fn demote_records_above(
    transactions: &mut BTreeMap<Txid, TransactionRecord>,
    height: CoreBlockHeight,
) -> Vec<Txid> {
    let to_demote: Vec<Txid> = transactions
        .iter()
        .filter_map(|(txid, record)| match record.context.block_info() {
