// Then inside the loop, before inserting outputs:
let has_owned_input = tx.input.iter().any(|input| self.utxos.contains_key(&input.previous_output));

// Option B – pre-pass:
let our_outpoints: HashSet<OutPoint> = self.keys.transactions().values()
    .filter(|r| !r.context.is_inactive())
    .flat_map(|r| {
        let txid = r.transaction.txid();
        (0..r.transaction.output.len() as u32).map(move |vout| OutPoint { txid, vout })
    })
    .collect();
// Then: let has_owned_input = tx.input.iter().any(|i| our_outpoints.contains(&i.previous_output));
```
</details>

